const ONBOARDING_CSS = `
.prd-onb {
  background: var(--paper);
  width: 100%; height: 100%;
  display: flex; flex-direction: column;
  padding: 32px 0 28px 0;
  box-sizing: border-box;
}
.prd-onb__progress {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  padding: 0 56px;
}
.prd-onb__progress > span {
  height: 2px; border-radius: 999px;
  background: var(--rule);
  transition: background .25s ease-out;
}
.prd-onb__progress > span.is-on { background: var(--coral); }

.prd-onb__body {
  flex: 1;
  display: flex; flex-direction: column;
  padding: 28px 32px 0 32px;
  min-height: 0;
}

.prd-onb__plate-strip {
  display: flex; justify-content: space-between;
  font-family: var(--font-mono); font-size: 10px;
  letter-spacing: 0.14em; color: var(--ink-2);
  text-transform: uppercase;
  padding: 0 32px 12px 32px;
}

.prd-onb__eyebrow {
  font-family: var(--font-mono);
  font-size: 10px; font-weight: 500;
  letter-spacing: 0.14em; color: var(--coral);
  text-transform: uppercase;
}
.prd-onb__title {
  font-family: var(--font-display);
  font-weight: 700; color: var(--ink);
  letter-spacing: -0.01em; line-height: 1.05;
  font-size: 38px;
  margin: 6px 0 0 0;
}
.prd-onb__sub {
  font-family: var(--font-body); font-style: italic;
  font-size: 14px; color: var(--ink-2);
  line-height: 1.55;
  margin: 12px 0 0 0;
}

.prd-onb__feature {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 14px;
  padding: 18px 0;
  border-top: 1px solid var(--rule);
}
.prd-onb__feature:last-child { border-bottom: 1px solid var(--rule); }
.prd-onb__feature-num {
  font-family: var(--font-mono);
  font-size: 10px; font-weight: 500;
  letter-spacing: 0.10em; color: var(--coral);
  padding-top: 2px;
}
.prd-onb__feature-title {
  font-family: var(--font-display);
  font-size: 16px; font-weight: 700;
  color: var(--ink); letter-spacing: -0.01em;
}
.prd-onb__feature-desc {
  font-family: var(--font-body);
  font-size: 13px; color: var(--ink-2); line-height: 1.5;
  margin-top: 3px;
}

.prd-onb__row {
  padding: 14px 0;
  border-top: 1px solid var(--rule);
  display: flex; justify-content: space-between; align-items: center;
}
.prd-onb__row:last-child { border-bottom: 1px solid var(--rule); }
.prd-onb__row-label {
  font-family: var(--font-display);
  font-size: 15px; font-weight: 600; color: var(--ink);
}
.prd-onb__row-hint {
  font-family: var(--font-body); font-style: italic;
  font-size: 12px; color: var(--ink-3);
  display: block; margin-top: 2px;
}
.prd-onb__row-action {
  font-family: var(--font-mono);
  font-size: 11px; font-weight: 500;
  letter-spacing: 0.12em;
  color: var(--coral);
  text-transform: uppercase;
  cursor: pointer;
}
.prd-onb__row-action.is-on { color: var(--mood-energized, #2D8A4E); }

.prd-onb__chip-row {
  display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px;
}
.prd-onb__chip {
  font-family: var(--font-mono); font-size: 11px; font-weight: 500;
  letter-spacing: 0.12em;
  padding: 8px 14px; border-radius: 999px;
  border: 1px solid var(--rule);
  background: var(--card);
  color: var(--ink-2);
  cursor: pointer;
  text-transform: uppercase;
}
.prd-onb__chip.is-active {
  background: transparent; color: var(--coral); border-color: var(--coral);
}

.prd-onb__time {
  display: grid;
  grid-template-columns: 60px 12px 60px 12px 60px;
  gap: 6px; align-items: center;
  margin-top: 14px;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}
.prd-onb__time-col {
  display: flex; flex-direction: column;
  align-items: center;
  padding: 6px 0;
  background: var(--card);
  border-radius: 10px;
}
.prd-onb__time-col select {
  appearance: none; -webkit-appearance: none;
  background: transparent; border: 0; outline: 0;
  font-family: var(--font-mono);
  font-size: 22px; font-weight: 600;
  color: var(--ink);
  text-align: center; text-align-last: center;
  width: 100%; padding: 4px 0;
}
.prd-onb__time-col label {
  font-family: var(--font-mono);
  font-size: 9px; letter-spacing: 0.12em;
  color: var(--ink-3);
  text-transform: uppercase;
}
.prd-onb__time-colon {
  font-family: var(--font-display);
  font-size: 22px; color: var(--ink-3);
  text-align: center;
}

.prd-onb__foot {
  padding: 18px 32px 0 32px;
  display: flex; flex-direction: column; gap: 12px;
}
.prd-onb__skip {
  text-align: center;
  font-family: var(--font-mono);
  font-size: 11px; letter-spacing: 0.12em;
  color: var(--ink-3); cursor: pointer;
  text-transform: uppercase;
  padding: 6px 0;
}

.prd-onb__tip {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 14px;
  padding: 14px 0;
  border-top: 1px solid var(--rule);
  align-items: baseline;
}
.prd-onb__tip:last-child { border-bottom: 1px solid var(--rule); }
.prd-onb__tip-n {
  font-family: var(--font-mono);
  font-size: 10px; font-weight: 600;
  letter-spacing: 0.10em; color: var(--coral);
}
.prd-onb__tip-text {
  font-family: var(--font-body);
  font-size: 14px; color: var(--ink); line-height: 1.5;
}
`;
